#!/bin/bash
set -e

mkdir -p app/src/main/assets/www
mkdir -p app/src/main/java/com/medicore/hms
mkdir -p app/src/main/res/values
mkdir -p app/src/main/res/mipmap-{mdpi,hdpi,xhdpi,xxhdpi,xxxhdpi}
mkdir -p gradle/wrapper

echo "=== Writing HTML app ==="
echo "" | base64 -d > app/src/main/assets/www/index.html
echo "HTML: $(wc -c < app/src/main/assets/www/index.html) bytes"

echo "=== Writing Gradle files ==="
cat > settings.gradle << 'EOF'
rootProject.name = "MediCore HMS"
include ':app'
EOF

cat > build.gradle << 'EOF'
buildscript {
  repositories { google(); mavenCentral() }
  dependencies { classpath 'com.android.tools.build:gradle:8.2.2' }
}
allprojects { repositories { google(); mavenCentral() } }
EOF

echo "org.gradle.jvmargs=-Xmx2048m
android.useAndroidX=true
android.enableJetifier=true" > gradle.properties

cat > app/build.gradle << 'EOF'
plugins { id 'com.android.application' }
android {
  namespace 'com.medicore.hms'
  compileSdk 34
  defaultConfig {
    applicationId "com.medicore.hms"
    minSdk 24; targetSdk 34
    versionCode 2; versionName "2.0.0"
  }
  buildTypes {
    debug { debuggable true }
    release { minifyEnabled false; signingConfig signingConfigs.debug }
  }
  compileOptions {
    sourceCompatibility JavaVersion.VERSION_17
    targetCompatibility JavaVersion.VERSION_17
  }
}
dependencies { implementation 'androidx.appcompat:appcompat:1.6.1' }
EOF

echo "=== Writing AndroidManifest ==="
cat > app/src/main/AndroidManifest.xml << 'EOF'
<?xml version="1.0" encoding="utf-8"?>
<manifest xmlns:android="http://schemas.android.com/apk/res/android">
  <uses-permission android:name="android.permission.INTERNET"/>
  <application android:allowBackup="true" android:icon="@mipmap/ic_launcher"
    android:label="MediCore HMS" android:theme="@style/AppTheme" android:usesCleartextTraffic="true">
    <activity android:name=".MainActivity" android:exported="true"
      android:screenOrientation="portrait" android:windowSoftInputMode="adjustResize">
      <intent-filter>
        <action android:name="android.intent.action.MAIN"/>
        <category android:name="android.intent.category.LAUNCHER"/>
      </intent-filter>
    </activity>
  </application>
</manifest>
EOF

echo "=== Writing MainActivity ==="
cat > app/src/main/java/com/medicore/hms/MainActivity.java << 'EOF'
package com.medicore.hms;
import android.annotation.SuppressLint;
import android.app.Activity; import android.app.AlertDialog;
import android.graphics.Color; import android.os.Build; import android.os.Bundle;
import android.view.Window; import android.view.WindowManager; import android.webkit.*;
public class MainActivity extends Activity {
  private WebView webView;
  @SuppressLint("SetJavaScriptEnabled")
  @Override protected void onCreate(Bundle savedInstanceState) {
    super.onCreate(savedInstanceState);
    requestWindowFeature(Window.FEATURE_NO_TITLE);
    getWindow().setFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN,WindowManager.LayoutParams.FLAG_FULLSCREEN);
    if(Build.VERSION.SDK_INT>=21){getWindow().setStatusBarColor(Color.parseColor("#060e17"));getWindow().setNavigationBarColor(Color.parseColor("#060e17"));}
    webView=new WebView(this); webView.setBackgroundColor(Color.parseColor("#060e17")); setContentView(webView);
    WebSettings s=webView.getSettings();
    s.setJavaScriptEnabled(true); s.setDomStorageEnabled(true); s.setAllowFileAccess(true);
    s.setAllowFileAccessFromFileURLs(true); s.setAllowUniversalAccessFromFileURLs(true);
    s.setBuiltInZoomControls(false); s.setSupportZoom(false); s.setUseWideViewPort(true); s.setLoadWithOverviewMode(true);
    webView.setWebViewClient(new WebViewClient()); webView.setWebChromeClient(new WebChromeClient());
    webView.loadUrl("file:///android_asset/www/index.html");
  }
  @Override public void onBackPressed(){if(webView.canGoBack())webView.goBack();else new AlertDialog.Builder(this).setTitle("Exit").setMessage("Exit MediCore?").setPositiveButton("Exit",(d,w)->finish()).setNegativeButton("Cancel",null).show();}
  @Override protected void onResume(){super.onResume();webView.onResume();}
  @Override protected void onPause(){super.onPause();webView.onPause();}
  @Override protected void onDestroy(){if(webView!=null)webView.destroy();super.onDestroy();}
}
EOF

echo "=== Writing resources ==="
echo '<?xml version="1.0" encoding="utf-8"?><resources><string name="app_name">MediCore HMS</string></resources>' > app/src/main/res/values/strings.xml
cat > app/src/main/res/values/styles.xml << 'EOF'
<?xml version="1.0" encoding="utf-8"?>
<resources>
  <style name="AppTheme" parent="Theme.AppCompat.NoActionBar">
    <item name="android:windowBackground">#060e17</item>
    <item name="android:statusBarColor">#060e17</item>
    <item name="android:navigationBarColor">#060e17</item>
  </style>
</resources>
EOF

echo "=== Writing icons ==="
echo "" | base64 -d > app/src/main/res/mipmap-mdpi/ic_launcher.png
cp app/src/main/res/mipmap-mdpi/ic_launcher.png app/src/main/res/mipmap-mdpi/ic_launcher_round.png
echo "" | base64 -d > app/src/main/res/mipmap-hdpi/ic_launcher.png
cp app/src/main/res/mipmap-hdpi/ic_launcher.png app/src/main/res/mipmap-hdpi/ic_launcher_round.png
echo "" | base64 -d > app/src/main/res/mipmap-xhdpi/ic_launcher.png
cp app/src/main/res/mipmap-xhdpi/ic_launcher.png app/src/main/res/mipmap-xhdpi/ic_launcher_round.png
echo "" | base64 -d > app/src/main/res/mipmap-xxhdpi/ic_launcher.png
cp app/src/main/res/mipmap-xxhdpi/ic_launcher.png app/src/main/res/mipmap-xxhdpi/ic_launcher_round.png
echo "" | base64 -d > app/src/main/res/mipmap-xxxhdpi/ic_launcher.png
cp app/src/main/res/mipmap-xxxhdpi/ic_launcher.png app/src/main/res/mipmap-xxxhdpi/ic_launcher_round.png
echo "Icons OK"

echo "=== Setting up Gradle wrapper ==="
echo "distributionBase=GRADLE_USER_HOME
distributionPath=wrapper/dists
distributionUrl=https\://services.gradle.org/distributions/gradle-8.4-bin.zip
zipStoreBase=GRADLE_USER_HOME
zipStorePath=wrapper/dists" > gradle/wrapper/gradle-wrapper.properties

wget -q https://services.gradle.org/distributions/gradle-8.4-bin.zip -O /tmp/gradle.zip
unzip -q -n /tmp/gradle.zip -d /tmp/
export PATH=$PATH:/tmp/gradle-8.4/bin
gradle wrapper --gradle-version 8.4
chmod +x gradlew

echo "=== Building APK ==="
./gradlew assembleDebug --no-daemon

echo "=== BUILD COMPLETE ==="
ls -lh app/build/outputs/apk/debug/
